import { test, expect } from '@playwright/test';

test.describe('Notifications', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should mark all notifications as read', async ({ page }) => {
    await expect(page.getByText('You have 5 new notifications')).toBeVisible();
    await page.getByRole('button', { name: 'Mark all as read' }).click();
    await expect(page.getByText('All notifications marked as read')).toBeVisible();
  });

  test('should verify all notifications are marked as read', async ({ page }) => {
    await page.getByRole('button', { name: 'Mark all as read' }).click();
    const notifications = await page.getByRole('listitem').all();
    for (const notification of notifications) {
      await expect(notification).toHaveClass(/read/);
    }
  });
});
